    "/api/enroll": {
      "post": {
        "summary": "Enroll a new student",
        "description": "Generates a unique student ID (format: adjective-noun-nnnn) and creates an empty progress record.",
        "requestBody": {
          "required": false,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "deviceId": {
                    "type": "string",
                    "format": "uuid",
                    "description": "Anonymous device identifier generated by the client."
                  }
                }
              }
            }
          }
        },
        "responses": {
          "201": {
            "description": "Student enrolled",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "studentId": {
                      "type": "string"
                    },
                    "progress": {
                      "$ref": "#/components/schemas/Progress"
                    }
                  },
                  "required": [
                    "studentId",
                    "progress"
                  ]
                }
              }
            }
          }
        }
      }
    },
    "/api/progress/{studentId}": {
      "get": {
        "summary": "Get student progress",
        "description": "Returns the student's progress, including which lessons and exercises they have completed.",
        "parameters": [
          {
            "name": "studentId",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Progress found",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Progress"
                }
              }
            }
          },
          "400": {
            "description": "Invalid student ID format",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "404": {
            "description": "Student not found",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      },
      "put": {
        "summary": "Mark a lesson or exercise as complete",
        "description": "Marks a lesson or exercise as complete for the given student. Supply either lessonSlug or exerciseSlug (not both). Idempotent.",
        "parameters": [
          {
            "name": "studentId",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            }
          }
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "lessonSlug": {
                    "type": "string",
                    "description": "Slug of the lesson to mark complete."
                  },
                  "exerciseSlug": {
                    "type": "string",
                    "description": "Slug of the exercise to mark complete."
                  },
                  "source": {
                    "type": "string",
                    "enum": [
                      "browser",
                      "agent"
                    ],
                    "description": "Who marked the item complete."
                  },
                  "model": {
                    "type": "string",
                    "description": "The model ID used by the agent. Agents should always include this."
                  }
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Progress updated",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Progress"
                }
              }
            }
          },
          "400": {
            "description": "Invalid request",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "404": {
            "description": "Student not found",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      },
      "delete": {
        "summary": "Undo a completion or reset all progress",
        "description": "Send { \"lessonSlug\": \"...\" } to uncomplete a lesson, { \"exerciseSlug\": \"...\" } to uncomplete an exercise, or { \"reset\": true } to clear all completions.",
        "parameters": [
          {
            "name": "studentId",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            }
          }
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "lessonSlug": {
                    "type": "string"
                  },
                  "exerciseSlug": {
                    "type": "string"
                  },
                  "reset": {
                    "type": "boolean"
                  }
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Progress updated",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Progress"
                }
              }
            }
          },
          "400": {
            "description": "Invalid request",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "404": {
            "description": "Student not found",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    },
